"""Six-query batch, checked 12 November 2026."""
from warhammer_survivors_pages import ROOT, BASE, render, external
from site_analytics import write_html

FAQ = 'https://aurochdigital.com/warhammer-survivors-faq'
PATCH = 'https://store.steampowered.com/news/app/3669620'
WIKI = 'https://wikily.gg/warhammer-survivors/'


def picture(name, alt, width, height):
    return f'<figure style="max-width:{width}px;margin:24px auto"><img src="/assets/warhammer-survivors/{name}.webp" alt="{alt}" width="{width}" height="{height}" loading="lazy" style="max-width:100%;height:auto;image-rendering:pixelated"></figure>'


def build(template):
    pages = [
        ('legend-of-catachan', 'Warhammer Survivors Legend of Catachan Unlock Guide',
         'Rescue the Legend of Catachan on Imperial Bastion, check the demo reset, and distinguish his Frag Grenade weapon from the launch Chainsword bug.',
         'Unlock the Legend of Catachan',
         'Rescue the Legend of Catachan on Imperial Bastion in the Warhammer 40,000 universe. Check character selection after the run to use him as your champion.', [
             ('rescue', 'Complete the Imperial Bastion rescue', '<ol><li>Select the 40K universe and start Imperial Bastion with an available champion.</li><li>Explore for the captive and approach with room to fight the guards.</li><li>Defeat the highlighted enemies surrounding him and complete the rescue.</li><li>Check character selection for the unlocked Legend on your next run.</li></ol><p>The rescue location is reported by '+external('https://primagames.com/tips/how-to-unlock-all-characters-in-warhammer-survivors', 'Prima Games')+'. The guard-clearing sequence is described by '+external('https://howtovideogame.com/warhammer-survivors-legend-of-catachan/', 'How to Video Game')+'. Neither establishes a fixed compass direction from every spawn.</p>'+picture('catachan','The Legend of Catachan in-game character portrait',176,256)),
             ('weapon', 'Frag Grenade and the rescued-character bug', '<p>His starting weapon is Frag Grenade. Steam hotfix v2.1.6, published 11 November, fixes a rescued Legend incorrectly using a Chainsword. The developer schedules the changes on other platforms from the following week. Check your installed version if the rescued ally still carries the wrong weapon. '+external(PATCH,'Developer hotfix announcements')+'</p><p>For the Frag Grenade evolution, match Bandolier in the <a href="/warhammer-survivors/evolutions/">recipe finder</a>. The companion unlock and the evolution attempt are separate checks.</p>'),
             ('demo', 'If you already played him in the demo', '<p>The October demo offered the Legend as a playable hero. Demo progress does not transfer into the released game, so rescue him in your full-game save. '+external('https://www.warhammer-community.com/en-gb/articles/m5cfelii/try-the-new-demo-for-warhammer-survivors-now/','Official demo announcement')+'</p><p>The portrait above is an in-game asset reproduced by '+external(WIKI+'characters/the-legend-of-catachan','Wikily')+'. This guide combines published sources and has no site-run rescue test. Continue with <a href="/warhammer-survivors/tips/">first-run planning</a> or <a href="/warhammer-survivors/secrets/">Secrets access</a>.</p>'),
         ]),
        ('secrets', 'Warhammer Survivors Secrets Menu and Incantations',
         'Find the relic that opens Secrets in each universe, distinguish incantations from riddles, and check selected reported launch unlock codes.',
         'Warhammer Survivors Secrets menu',
         'Unlock Secrets through the relic for your selected universe. The Book of Tzeentch opens the 40K menu, while the Eye of Tzeentch opens the Age of Sigmar menu.', [
             ('access', 'Find the correct relic first', '<ul><li><strong>40K</strong> — find The Book of Tzeentch on Death World Invasion.</li><li><strong>Age of Sigmar</strong> — find the Eye of Tzeentch in Gnarlwood.</li></ul><p>Collect the corresponding relic, then inspect that universe’s Secrets menu. Locations and effects are listed in '+external('https://grindnstrat.com/warhammer-survivors-all-relics-guide-location-effects/','GrindnStrat’s relic guide')+'. The pictured Book is the 40K object, as identified by '+external(WIKI+'relics/the-book-of-tzeentch','Wikily’s relic entry')+'.</p>'+picture('book-tzeentch','The Book of Tzeentch in-game relic icon',112,112)),
             ('entry', 'Use an incantation or follow a riddle', '<p>In Secrets, look for the incantation entry field. Type the reported word as shown, submit it, and check the named reward. Riddles instead describe objectives to carry out during play. Confirm the selected universe and its relic before troubleshooting a missing entry field.</p><p>These selected examples are community launch reports from '+external(WIKI+'secrets','Wikily’s Secrets reference')+'. They have not been entered in a live save by this site.</p><div class="table-wrap"><table><thead><tr><th>Reported incantation</th><th>Reward</th></tr></thead><tbody><tr><td><code>catachandevil</code></td><td>The Legend of Catachan</td></tr><tr><td><code>crimsonking</code></td><td>The Book of Tzeentch</td></tr><tr><td><code>arsenal</code></td><td>Standard weapons and passives</td></tr></tbody></table></div><p>A complete code catalogue and every riddle solution remain outside this page’s checked coverage. Broad unlock codes can change many unlock states, so choose the reward you intend before submitting.</p>'),
             ('normal-route', 'Continue through regular unlock objectives', '<p>For a regular character unlock, <a href="/warhammer-survivors/legend-of-catachan/">rescue the Legend of Catachan</a>. For item objectives, use <a href="/warhammer-survivors/followers/">two followers</a> or <a href="/warhammer-survivors/dice-cube/">Dice Cube</a>. Read the objective’s universe and whether it asks for one run before choosing a loadout.</p>'),
         ]),
        ('tips', 'Warhammer Survivors Tips for Your First Runs',
         'Plan your first Warhammer Survivors runs around clear objectives, unlock prerequisites and weapon pairs, with platform-specific chest and bug checks.',
         'Warhammer Survivors tips for your first runs',
         'Pick one visible objective before starting a run. Check its universe and prerequisites, then choose a weapon plan that also moves that objective forward.', [
             ('plan', 'Choose a run with a concrete goal', '<ol><li>Open Objectives in the universe you plan to play. Read whether progress is cumulative or must happen in one run.</li><li>For an early survival milestone, choose a character you already control reliably. The pictured 40K objective lists surviving one minute as the Tape Measure unlock.</li><li>For a rescue goal, choose the named stage. <a href="/warhammer-survivors/legend-of-catachan/">Catachan needs an Imperial Bastion rescue</a>.</li><li>After the attempt, check completion and available rewards before repeating it.</li></ol>'+picture('objectives','40K Objectives menu showing survival, rescue and follower unlock conditions',839,472)+'<p>Objectives screenshot by Destructoid, from its '+external('https://www.destructoid.com/all-items-in-warhammer-survivors-and-how-to-unlock-them/','launch item guide')+'. Use your installed build’s wording when it differs.</p>'),
             ('loadout', 'Check unlocks before planning an evolution', '<p>Choose one target pair in the <a href="/warhammer-survivors/evolutions/">evolution finder</a> and filter the universe. If its passive is locked, make that unlock your immediate goal. For Dice Cube, follow the <a href="/warhammer-survivors/dice-cube/">universe-specific objective</a>. Once both items are available, follow the weapon-upgrade and chest checks in the recipe guide.</p><p>For a follower goal, the <a href="/warhammer-survivors/followers/">two-follower route</a> explains the required weapons and prerequisites. Followers supply attacks during a solo run. For human player count, see <a href="/warhammer-survivors/co-op/">co-op status</a>.</p>'),
             ('version', 'Check the platform before applying a fix', '<p>Steam hotfix v2.1.6 makes chest sequences skippable with any button and fixes unreachable chest drops on Imperial Bastion and Gallowdark. Its 11 November announcement schedules other platforms from the following week. '+external(PATCH,'Developer patch notes')+'</p><p>Keep your platform and installed version with a bug report. These planning tips combine documented objectives and existing guides, with no site-run performance or build-ranking test. Check <a href="/warhammer-survivors/#switch-2">Switch 2 access and controls</a> or <a href="/warhammer-survivors/secrets/">Secrets menu access</a> for your next task.</p>'),
         ]),
    ]
    for slug, title, description, heading, answer, sections in pages:
        path = ROOT/'warhammer-survivors'/slug/'index.html'
        path.parent.mkdir(parents=True, exist_ok=True)
        text = render(template, BASE+slug+'/', title, description, heading, '<p>'+answer+'</p>', sections, 'squad')
        text = text.replace('WARHAMMER SURVIVORS · OCTOBER DEMO / PRE-RELEASE', 'WARHAMMER SURVIVORS · PLAYER GUIDE')
        text = text.replace('Checked 8 November 2026 · Full game planned for 10 November', 'Checked 12 November 2026 · Platform-specific launch updates')
        text = text.replace('<div class="table-wrap">', '<div class="table-wrap" tabindex="0" role="region" aria-label="Reported incantations, scroll horizontally">')
        write_html(path, text, encoding='utf8')


def patch_home(text):
    cards = ''.join(f'<a class="task-card" href="{BASE}{slug}/"><h3>{title}</h3><p>{summary}</p><span class="card-action">Read the guide →</span></a>' for slug,title,summary in [
        ('tips','First-run tips','Choose an objective and plan the next unlock.'),
        ('legend-of-catachan','Legend of Catachan','Rescue the champion and check the launch weapon bug.'),
        ('secrets','Secrets & incantations','Open the right universe’s menu and understand reported codes.')])
    text = text.replace('<section id="release"', '<section class="progression-section" id="reference"><div class="section-heading"><h2>Start & explore</h2><p>Looking for a Warhammer Survivors wiki? Start with these checked task guides.</p></div><div class="task-grid">'+cards+'</div></section><section id="release"',1)
    details = f'''<details class="help-item" id="android"><summary>Android download & APK searches</summary><div class="help-body"><p>Use the official Google Play listing for Warhammer Survivors by Auroch Digital, package <code>com.AurochDigital.WarhammerSurvivors</code>. Open it with the Google account and Android device you intend to use, check compatibility and the local purchase price, then install through Play. {external('https://play.google.com/store/apps/details?id=com.AurochDigital.WarhammerSurvivors','Official Google Play purchase and installation')}</p><p>Checked 12 November 2026. No standalone developer APK download has been verified in this review. Direct APK sideloading and installation on devices without Google Play remain unresolved.</p></div></details>
<details class="help-item" id="switch-2"><summary>Nintendo Switch 2 access & launch fixes</summary><div class="help-body"><p>Auroch lists Nintendo Switch 1 and 2 among the released platforms. Choose your console and region through the {external('https://aurochdigital.com/warhammer-survivors','official game page')} and confirm the Nintendo eShop product before purchase. The developer’s FAQ advises using the joystick if a Switch Pro Controller d-pad does not navigate menus on Switch 2. {external(FAQ,'Developer platform and known-issue FAQ')}</p><p>The 11 November Steam hotfix v2.1.6 schedules its changes for Switch 1 and 2 from the following week. Check your installed version before expecting the rescued Catachan weapon fix or the updated chest controls. {external(PATCH,'Developer hotfix notes')}</p><p>Checked 12 November 2026. Native-edition versus compatibility differences, measured frame rate and handheld battery life have not been established by this review.</p></div></details>'''
    return text.replace('<div class="editorial-note">',details+'<div class="editorial-note">',1)
